from lib import *
S = SS('w24')
steps = [
    step("本机的 IPv6 地址清单(ifconfig):8 个接口共 9 个地址——lo0 有回环 ::1 和一个链路本地地址,en0、awdl0、llw0、utun0~utun3 各有一个 fe80::/10 链路本地地址(都是 /64,带作用域编号),en0 的那个带 secured 标志。全球单播和唯一本地地址一个也没有(0 个):这台机器所在的网络没有给它分配可路由的 IPv6 地址,所以没有公网 IPv6 连通性,本篇和接下来几篇的 IPv6 实验都在本地链路和回环上做。", t=tl(S(1)), mark=lidx(S(1), 'en0    链路本地', '按类型统计'), done=lidx(S(1), '有 IPv6 地址的接口', 'lo0    回环', 'awdl0', 'utun0'), b=bars([['链路本地 fe80::/10', 8, '8'], ['回环 ::1', 1, '1'], ['全球单播 / 唯一本地', 0, '0']], 8, mark=[2], done=[0, 1]), kv=KV([['接口', '8 个,共 9 个 IPv6 地址'], ['链路本地', '8 个(每个接口一个)'], ['全球单播', '0 个:没有公网 IPv6']], ['全球单播'])),
    step("IPv6 地址的写法:同一个地址可以有很多种。把 2001:db8::1 按“每组可补前导 0 + 压缩任意一段连续的 0 组(或不压缩)”枚举(只算小写),共 20936 种,经 ipaddress 解析都等于 2001:db8::1。RFC 5952 规定输出只用一种:去掉前导 0、小写、压缩最长的连续 0 组(等长取最左)、单个 0 组不压缩——所以 2001:db8:0:0:1:0:0:1 压缩成 2001:db8::1:0:0:1(两段等长取最左),2001:db8:0:1:1:1:1:1 里只有一个 0 组,不压缩;0:0:0:0:0:0:0:1 → ::1,全零 → ::,FE80::0202:B3FF:FE1E:8329 → fe80::202:b3ff:fe1e:8329。::ffff:192.0.2.128 是 IPv4 映射地址(Python 的 ipv4_mapped 取出 192.0.2.128),64:ff9b::/96 是 NAT64 的转换前缀。", t=tl(S(2)), mark=lidx(S(2), '2001:db8::1 这一个地址', '2001:db8:0:0:1:0:0:1', '2001:db8:0:1:1:1:1:1'), done=lidx(S(2), '输入', '0:0:0:0:0:0:0:1', 'FE80::', '::ffff:192.0.2.128 是'), b=bars([['2001:db8::1 的合法写法', 20936, '20936 种'], ['RFC 5952 的标准写法', 1, '1 种']], 20936, mark=[0], done=[1]), kv=KV([['合法写法', '20936 种(仅小写)'], ['标准写法', '去前导 0、小写、压缩最长 0 段'], ['等长两段 0', '压缩最左边的'], ['单个 0 组', '不压缩']], ['标准写法'])),
    step("IPv6 地址空间(查表加计算):全球单播 2000::/3 占整个 128 位空间的 1/8(1.250e-01);唯一本地 fc00::/7 占 7.812e-03;链路本地 fe80::/10 占 9.766e-04;组播 ff00::/8 占 3.906e-03;文档用 2001:db8::/32 占 2.328e-10。一个 /64 子网有 2^64 个地址,是整个 IPv4 空间的 4,294,967,296 倍。Python 的分类:::1 是 loopback 和 private;fe80::1 是 private 加 link-local;fd12:3456::1(唯一本地)和文档地址 2001:db8::1 是 private;2606:4700:4700::1111 是 global;ff02::1 同时是 global 和 multicast;64:ff9b::192.0.2.1 是 global,::ffff:192.0.2.1 是 private——is_global / is_private 对特殊地址的判定有时出乎意料,要看清楚再用。", t=tl(S(3)), mark=lidx(S(3), '2000::/3', 'fc00::/7', 'ff00::/8'), done=lidx(S(3), '::1/128', 'fe80::/10', '样本地址', '全球单播 2000::/3 占'), kv=KV([['2000::/3', '1/8 的空间,全球单播'], ['fc00::/7', '唯一本地(类似私有地址)'], ['fe80::/10', '链路本地'], ['ff00::/8', '组播'], ['一个 /64 子网', '= 整个 IPv4 空间的 4,294,967,296 倍']], ['2000::/3'])),
    step("作用域实测:链路本地地址只在一条链路上有意义,发送时必须告诉内核走哪个接口。在 lo0 上用 fe80::1 收发成功(套接字地址是四元组,scope_id=1 就是 lo0 的接口编号);往本机自己 en0 的链路本地地址发 UDP:scope_id=0(不带接口)报 No route to host,scope_id 设成 en0 的编号才发送成功;往邻居表里的一个邻居发,也是 scope_id=0 失败、带 en0 编号成功。向本链路所有节点 ff02::1 ping(-I en0,3 次):共收到 284 个应答,来自 146 个不同的链路本地地址,应答的跳数限制 64 的占 264 个、255 的 17 个、63 的 2 个、254 的 1 个,本机自己也应答了;向所有路由器 ff02::2 ping:收到 51 个应答,来自 25 个地址(跳数限制 64 的 49 个,255 的 2 个)。en0 上加入了 5 个 IPv6 组播组:ff01 接口本地 1 个,ff02 链路本地 4 个。", t=tl(S(4)), mark=lidx(S(4), 'scope_id = 0', 'ff02::1:共收到', 'ff02::2:共收到'), done=lidx(S(4), 'fe80::1%lo0 上收发', 'scope_id = en0 的编号', 'en0 上加入的 IPv6 组播组'), b=bars([['ff02::1 应答来自的地址', 146, '146'], ['ff02::2 应答来自的地址', 25, '25']], 146, mark=[0], done=[1]), kv=KV([['链路本地 + 无接口', 'No route to host'], ['链路本地 + 接口编号', '发送成功'], ['ff02::1', '146 个不同地址应答'], ['ff02::2', '25 个不同地址应答']], ['链路本地 + 接口编号'])),
    step("接口标识符(地址的后 64 位)怎么来:EUI-64 由 MAC 推出,中间插入 ff:fe 并翻转第 7 位。本机 en0 的链路本地地址的后 64 位与 MAC 推出的 EUI-64 不同——地址标志里是 secured,即稳定的不透明标识符,不是从 MAC 推出的。邻居表里 en0 上有 MAC 的 172 个邻居,链路本地地址是 EUI-64 的有 80 个,不是的 92 个(地址不写出)。被请求节点组播地址是 ff02::1:ff 加地址的后 24 位,本机 en0 上已经加入了它——en0 上加入的这类组有 1 个,每个地址对应一个,邻居发现用它代替广播(下一篇)。", t=tl(S(5)), mark=lidx(S(5), '本机:MAC 推出', '邻居表', '被请求节点组播地址'), done=lidx(S(5), 'en0 上加入的组播组里'), b=bars([['邻居 · EUI-64 推出的', 80, '80'], ['邻居 · 不是 EUI-64', 92, '92']], 92, mark=[0], done=[1]), kv=KV([['EUI-64', 'MAC 中间插 ff:fe + 翻转第 7 位'], ['本机 en0', 'secured,不是 EUI-64'], ['172 个邻居', '80 个是 EUI-64'], ['被请求节点组播', 'ff02::1:ff + 后 24 位']], ['被请求节点组播'])),
]
A = mkartw('w24', 24, '网络协议,IPv6,IPv6地址,链路本地,EUI-64,作用域,组播,真实验证,动画演示',
    '本机 8 个接口共 9 个 IPv6 地址、全部是回环或链路本地(没有公网 IPv6);2001:db8::1 有 20936 种合法写法;链路本地地址必须带接口编号才能发送;ff02::1 ping 得到 146 个地址的应答;邻居里 80 / 172 个地址由 MAC 推出。',
    'IPv6 地址长什么样、怎么缩写、有哪些类型?为什么链路本地地址后面总要加“%en0”?邻居的地址是怎么生成的?这篇在本机上列出所有 IPv6 地址,枚举一个地址的所有写法,验证作用域规则,并向整条链路问一声“谁在”。',
    [('20936', '2001:db8::1 的合法文本写法数(仅小写),RFC 5952 只规定其中一种'), ('146', '向 ff02::1 ping 3 次,应答的不同链路本地地址个数'), ('80 / 172', '邻居表里链路本地地址由 MAC 推出(EUI-64)的个数,本机自己的则不是')],
    [('本机的地址', '<p>每个接口至少有一个 fe80::/10 链路本地地址,lo0 另有 ::1。本机网络没有分配全球单播地址,所以后面的 IPv6 实验都在本地链路上做。</p>'),
     ('写法', '<p>一个地址可以补前导 0 也可以压缩连续的 0 组,有两万多种写法;RFC 5952 规定输出时去前导 0、小写、压缩最长的 0 段(等长取最左)。</p>'),
     ('地址空间', '<p>2000::/3 是全球单播(占 1/8),fc00::/7 唯一本地,fe80::/10 链路本地,ff00::/8 组播。一个 /64 子网的地址数是整个 IPv4 空间的 43 亿倍。</p>'),
     ('作用域', '<p>链路本地地址在不同接口上可以重复,所以发送时必须带接口(scope_id);不带就是 No route to host。ff02::1 能一次问出整条链路上的几百个应答。</p>'),
     ('接口标识符', '<p>EUI-64 由 MAC 推出,已知邻居里约一半是这样,本机的 en0 是稳定的不透明标识符;被请求节点组播地址由地址的后 24 位决定。</p>')],
    steps,
    [ENV_W + '。本机网络没有公网 IPv6,所有实验都在回环和本地链路上;邻居与应答者的地址一律不写出,只统计个数;ff02::1 / ff02::2 各 ping 3 次,应答数随当时在线的设备变化',
     '没有验证:全球单播地址的分配与前缀委派;临时地址(隐私扩展)的生成与轮换(本机没有全球地址);唯一本地地址 fd00::/8 的随机前缀算法;ff02::2 的应答者为什么有 25 个(不是路由器的设备也回应);跳数限制 63 / 254 的应答来自什么设备'],
    'IPv6 地址')
